    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: Current working directory (canonical absolute path)
        links: Dictionary mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """
    # Normalize path to absolute
    if not path.startswith('/'):
        path = cwd + '/' + path

    # Split path into components
    components = path.split('/')

    # Start with root
    current = ''
    link_count = 0

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '':
                current = ''
            else:
                # Remove last component
                current = current.rsplit('/', 1)[0]
            continue

        # Append component
        if current == '':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute symlink target
                current = target
